  # closing tags
  while (match($0, /<\/[a-zA-Z][a-zA-Z0-9]*>/)) {
    tag = substr($0, RSTART+3, RLENGTH-4); close[tag]++; $0 = substr($0, RSTART+RLENGTH);
  }
  # opening tags
  while (match($0, /<[a-zA-Z][a-zA-Z0-9]*/)) {
    tag = substr($0, RSTART+1, RLENGTH-RSTART); open[tag]++; $0 = substr($0, RSTART+RLENGTH);
  }
}
